import{_ as t}from"./chunks/architecture.C0g-L6KO.js";import{_ as a,o as r,c as o,a0 as n}from"./chunks/framework.Czcffv53.js";const m=JSON.parse('{"title":"shared-agent-framework","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),s={name:"index.md"};function h(i,e,d,l,g,u){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="shared-agent-framework" tabindex="-1">shared-agent-framework <a class="header-anchor" href="#shared-agent-framework" aria-label="Permalink to &quot;shared-agent-framework&quot;">​</a></h1><p>A framework for AI agents that act for more than one party at the same time, and are controlled by none of them individually.</p><h2 id="what-a-shared-agent-is" tabindex="-1">What a Shared Agent is <a class="header-anchor" href="#what-a-shared-agent-is" aria-label="Permalink to &quot;What a Shared Agent is&quot;">​</a></h2><p>A <strong>Shared Agent</strong> is an AI agent that acts for several parties at once. No single party owns it, and no party can reach it privately. Every message into the agent and out of it goes through a <strong>Gateway</strong> that you run.</p><p>Two people who share a household budget are a good example. Both talk to the same agent. Both need to trust that the agent does not take instructions from one of them in secret. The Gateway is what makes that structure real. It holds the Message log and the agent&#39;s signing key. It is the only path between a person and the agent.</p><p>An <strong>Operator</strong> is whoever runs and configures a Shared Agent. Every party trusts the Operator. The Operator writes the entry point, holds the keys, owns the database, and runs the stack. Most of this site is written for that reader.</p><p><img src="'+t+`" alt="The parts of a Shared Agent. A dashed boundary encloses the Gateway, holding the Db, the Signal
Worker, the Agent server and the Public server, together with the Messenger and its two Channels
and Users with its two Auths. Outside it are the Agent Implementation, a person&#39;s client, and a
Nostr Relay."></p><p>Everything inside the dashed boundary is the Gateway. The <a href="./architecture.html#the-shape">Architecture</a> page reads the picture part by part.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it answers</th></tr></thead><tbody><tr><td><a href="./guide.html">Build a Shared Agent</a></td><td>How do I get a working deployment from nothing?</td></tr><tr><td><a href="./architecture.html">Architecture</a></td><td>What are the parts, and why are they separate?</td></tr><tr><td><a href="./reference/">API reference</a></td><td>What is the exact signature of this function?</td></tr></tbody></table><p>Read the guide first. It builds one small deployment step by step, and it links to the architecture page wherever a step needs the reasoning behind it.</p><h2 id="what-the-framework-gives-you" tabindex="-1">What the framework gives you <a class="header-anchor" href="#what-the-framework-gives-you" aria-label="Permalink to &quot;What the framework gives you&quot;">​</a></h2><ul><li>A <strong>Gateway</strong> that mediates all traffic between people and the agent.</li><li>A <strong>serial Signal Worker</strong>, so the agent does one thing at a time.</li><li><strong>Messaging</strong> over HTTP or Nostr, with one Message log per person.</li><li><strong>Authentication</strong> as a component, with passwords or Nostr keys.</li><li><strong>Signed Decisions</strong>, so the agent can commit to something that a third party can check.</li><li><strong>Scheduling</strong>, so time can wake the agent.</li></ul><p>You choose which of these your deployment builds. The framework builds only the infrastructure that every deployment needs, and you construct the rest by hand.</p><h2 id="what-you-must-provide-yourself" tabindex="-1">What you must provide yourself <a class="header-anchor" href="#what-you-must-provide-yourself" aria-label="Permalink to &quot;What you must provide yourself&quot;">​</a></h2><p>The framework does not do these things, and each omission is deliberate:</p><ul><li><strong>Confidentiality between parties.</strong> The agent reads every Message and decides what to send to whom.</li><li><strong>Resistance to prompt injection.</strong> This risk is accepted, not solved.</li><li><strong>Confinement of the Agent Implementation.</strong> Your deployment confines it.</li><li><strong>Rate limiting.</strong> The login route is unthrottled.</li></ul><p>The <a href="./architecture.html#what-you-must-provide-yourself">Architecture</a> page states the full list. Read it before you deploy.</p>`,18)])])}const f=a(s,[["render",h]]);export{m as __pageData,f as default};
